  'vec.add': "Adicionar coluna vetorial",
  'docv.add': "Vista de documento",
  'vec.title': "Coluna vetorial em {table}",
  'vec.intro': "Adiciona uma coluna de embedding vector(n) (n: as dimensões do fornecedor de vetores), um índice HNSW para a distância e um gatilho que recalcula o embedding de uma linha quando as colunas de origem mudam. Uma configuração de pesquisa do tipo vector ou hybrid, ou a ferramenta Retrieve de um agente de IA, encontra então as linhas pelo significado. As linhas que já existem entram logo na fila para os seus embeddings.",
  'vec.existing': "Colunas vetoriais atuais",
  'vec.provider': "Fornecedor de vetores",
  'vec.provider_help': "Componentes partilhados › Fornecedores de vetores das aplicações deste espaço de trabalho. Pesquise com o mesmo fornecedor.",
  'vec.keep': "Manter atualizada",
  'vec.keep_help': "Um fornecedor do tipo função pode definir o embedding no gatilho, de imediato. Um serviço de IA é chamado pelo servidor: o gatilho põe a linha na fila e o servidor calcula os embeddings em lotes, dentro dos pedidos por minuto do fornecedor e dos limites diários de IA da aplicação.",
  'vec.mode_set': "definido pelo gatilho, de imediato",
  'vec.mode_queue': "na fila para o servidor",
  'vec.sources': "Colunas de origem",
  'vec.sources_help': "O texto de que se calcula o embedding: estas colunas, uma por linha. Uma alteração numa delas recalcula o embedding da linha.",
  'vec.distance': "Distância",
  'vec.distance_help': "cosine para a maioria dos modelos de embedding; a configuração de pesquisa usa a mesma distância.",
  'vec.column': "Coluna vetorial",
  'vec.no_key': "A tabela precisa de uma chave primária de uma só coluna: a fila encontra as linhas por ela.",
