  'st.header_title': 'Autenticação por cabeçalho HTTP',
  'st.header_intro': 'Usado somente quando a autenticação é “Cabeçalho HTTP”. Um proxy reverso ou gateway de login único autentica os usuários e passa o nome de usuário em um cabeçalho; o pgkiln só confia nele a partir dos endereços de proxy em {env}',
  'st.header_unset': 'não definido neste servidor: o login por cabeçalho é recusado',
  'st.header_name': 'Cabeçalho do nome de usuário',
  'st.header_name_help': 'O cabeçalho da requisição com o nome de usuário (APEX: HTTP Header Variable). Vazio: X-Remote-User. Um cabeçalho alterado ou ausente encerra a sessão.',
  'st.logout_url': 'URL de logout',
  'st.logout_url_ph': 'por exemplo https://sso.example.com/logout',
  'st.logout_url_help': 'Para onde “Sair” leva após o fim da sessão, normalmente a página de logout do próprio proxy. Vazio: uma página “sessão encerrada”.',
  'st.header_auto': 'Criar contas automaticamente',
  'st.header_auto_help': 'Um nome de usuário desconhecido recebe uma nova conta com acesso a esta aplicação. Caso contrário, a conta deve existir e ter acesso.',
  'st.db_title': 'Contas do banco de dados',
  'st.db_intro': 'Usado somente quando a autenticação é “Contas do banco de dados”. Os usuários entram com um papel de login do PostgreSQL e sua senha, verificados por uma conexão curta a este banco com esse papel. Superusuários e os papéis do próprio pgkiln são sempre recusados; sem nenhum dos dois campos ninguém pode entrar.',
  'st.db_roles': 'Papéis permitidos',
  'st.db_roles_ph': 'por exemplo alice, bob',
  'st.db_roles_help': 'Papéis de login que podem entrar, separados por vírgulas (nomes exatos).',
  'st.db_member': 'Ou membros do papel',
  'st.db_member_ph': 'por exemplo app_users_group',
  'st.db_member_help': 'Todos os membros deste papel também podem entrar.',
  'st.custom_title': 'Autenticação personalizada',
  'st.custom_intro': 'Usado somente quando a autenticação é “Personalizada”. Seu próprio PL/pgSQL verifica o nome de usuário e a senha do formulário, com o papel de banco de dados da aplicação; a senha é passada como parâmetro e nunca registrada. Tentativas falhas são limitadas como os outros logins. Sem nenhum dos dois campos ninguém pode entrar.',
  'st.custom_fn': 'Nome da função',
  'st.custom_fn_ph': 'por exemplo app.check_login',
  'st.custom_fn_help': 'Uma função (p_username text, p_password text) returns boolean, em minúsculas, opcionalmente com o esquema. O papel da aplicação precisa de EXECUTE nela. Tem prioridade sobre o corpo abaixo.',
  'st.custom_body': 'Ou corpo da função',
  'st.custom_body_help': 'PL/pgSQL com p_username e p_password, retornando true para um login válido, por exemplo {example}',
  'st.custom_post': 'Código pós-autenticação',
  'st.custom_post_help': 'PL/pgSQL opcional executado após uma verificação bem-sucedida, com p_username (e meta.app_user()), por exemplo para registrar o último login. Lançar uma exceção recusa o login. Processos de aplicação “after login” são executados depois, como de costume.',
