  'st.session_group': 'Grupo de compartilhamento de sessão',
  'st.session_group_ph': 'vazio: não compartilhada',
  'st.session_group_help': 'Aplicações do mesmo grupo (e com o diretório de usuários como autenticação) compartilham o login: após entrar em uma, as outras abrem sem novo login, cada uma com sua própria verificação de acesso e papéis; sair de uma sai de todas (APEX: session sharing). Letras minúsculas, dígitos e _.',
