  'rs.saving_needs_a_process_of': 'Guardar requer um processo do tipo "grid_dml" para esta região; sem ele a grelha é só de leitura.',
  'rs.column_sum_avg_count_min': 'coluna=sum, avg, count, min ou max; separe as colunas com ";". Calculado sobre todas as linhas da pesquisa, não só a página. Os utilizadores podem adicionar os seus (Ações → Agregado).',
  'rs.stay_in_view_while_the': 'Ficam visíveis enquanto a grelha desliza na horizontal. Os utilizadores podem alterá-lo, mover, redimensionar e ocultar colunas; "layout" no JSON define a ordem e as larguras predefinidas.',
  'rs.views_users_may_switch_to': 'Vistas para as quais os utilizadores podem mudar além da grelha. A vista de linha única edita uma linha de cada vez (também a partir do menu de ações de linha); agrupar e gráfico configuram-se em Ações.',
  'rs.a_master_grid_s_selected': 'A linha selecionada de uma grelha mestre coloca o seu valor num item de página; as grelhas de detalhe e os relatórios usam-no na sua consulta (:P1_ID) e são atualizados sem recarregar a página. Outros tipos de região seguem com {"master": {"item": "P1_ID"}}.',
  'rs.edit_as_picks_a_shared': '"Editar como" escolhe uma lista de valores partilhada (Componentes partilhados → Listas de valores) para uma lista de seleção.',
  'rs.the_visible_area_and_vector': 'A área visível e os mosaicos vetoriais precisam de `lat`/`lng` (ou de uma geometria PostGIS) e voltam a carregar quando o mapa se move. Os mosaicos vetoriais desenham pontos, linhas e áreas, sem agrupamento nem lista.',
  'rs.the_same_columns_as_the': 'As mesmas colunas que a consulta do mapa. Esvazie a consulta para remover a camada.',
  'rs.the_condition_runs_on_the': 'A condição corre no servidor: com o PostGIS instalado numa coluna geometry/geography, caso contrário na latitude e longitude.',
  'rs.users_switch_between_the_ticked': 'Os utilizadores alternam entre as vistas assinaladas. As horas fora do intervalo são acrescentadas quando um evento precisa delas.',
  'rs.runs_as_the_application_s': 'É executado com a função de base de dados da aplicação (aplica-se a segurança ao nível da linha) com `:EVENT_ID` (o valor da coluna-chave), `:NEW_START` e `:NEW_END` (a mesma duração de antes). Vazio: os eventos não podem ser arrastados.',
  'rs.only_events_the_user_sees': 'Só podem ser movidos os eventos que o utilizador vê neste calendário; sem rato, a ligação de edição altera as datas.',
  'rs.not_while_the_pointer_or': 'Não enquanto o ponteiro ou o foco estiverem no carrossel, nem para utilizadores que preferem movimento reduzido. Um carrossel não tem "Mostrar tudo".',
  'rs.a_chosen_region_gets_display': 'Uma região escolhida recebe `"display_selector": true` nas suas definições (um separador com o seu nome) ou o nome do separador: regiões com o mesmo nome de separador partilham um separador (p. ex. filtros inteligentes e o seu relatório). Sem JavaScript todas as regiões são mostradas, com ligações para cada uma.',
  'rs.gauge_charts_only_a_warning': 'Só gráficos de indicador. Um limiar de aviso acima do crítico significa que os valores baixos são maus (p. ex. aviso 50, crítico 20).',
  'rs.drill_down_column_takes_the': 'Detalhe: `#column#` usa o valor da linha do ponto e `#series#` o nome da sua série. As colunas a que só a ligação se refere não são desenhadas.',
  'rs.gantt_charts_with_a_task': 'Gráficos de Gantt com uma coluna `task_id`. É executado com a função de base de dados da aplicação (aplica-se a segurança ao nível da linha) com `:TASK_ID`, `:NEW_START` e `:NEW_END` (`YYYY-MM-DD`, ou `YYYY-MM-DDTHH:MM` à hora; um marco recebe o mesmo início e fim). Vazio: as tarefas não podem ser arrastadas.',
