  'rs.not_in_query': 'não está na consulta',
  'rpt.report_settings': 'Definições do relatório',
  'rpt.save_report_settings': 'Guardar definições do relatório',
  'rs.no_position_alert': 'O relatório não tem colunas `lat`/`lng` nem `location`, por isso a área do mapa não o pode filtrar.',
  'rs.facets_help': 'As caixas de verificação listam os valores mais frequentes (Excluir permite antes filtrá-los). Intervalos e De/até precisam de uma coluna numérica ou de data: os intervalos são `from..to = label` separados por `;`, com uma ponta aberta deixada vazia (`..1000`, `2020-01-01..`); um intervalo inclui o início, não o fim. Uma classificação por estrelas oferece «4 estrelas ou mais» e assim por diante (até 5; `"max"` no JSON altera isso).',
  'rs.facets_help_chart': 'Gráfico: um gráfico de barras ou circular das contagens sob a faceta (recolhido); uma barra ou fatia filtra pelo seu valor.',
  'rs.calendar_help': 'A consulta devolve `start_date`, `title` e opcionalmente `end_date` (datas para eventos de dia inteiro, timestamps para eventos com hora).',
  'rs.chart_help': 'A primeira coluna é a etiqueta; cada coluna numérica seguinte é uma série (até 8). Um gráfico de Gantt lê `label, start, end` (datas ou timestamps; um fim vazio é um marco) e colunas opcionais chamadas `progress` (0 a 100), `task_id` e `depends_on` (os ids de que uma tarefa está à espera, p. ex. `3,4`).',
  'rs.map_help': 'Cada linha é um marcador em `lat`, `lng` (ou `location` como "lat,lng"), com `title` e `body` no seu popup; uma coluna `geojson` desenha linhas e áreas (com o PostGIS instalado, também serve uma coluna `geometry` ou `geography` em WGS 84). Um mapa de calor pondera cada local por uma coluna `weight`.',
  'rs.tree_help': 'A consulta devolve `id`, `parent_id` e `label` (e opcionalmente `icon`); as linhas cujo pai não está no resultado são as raízes.',
  'rs.workflow_help': 'Os fluxos de trabalho vêm das definições de fluxo (Componentes Compartilhados); o SQL da aplicação inicia-os com `meta.start_workflow(…)`.',
  'rs.task_help': 'As tarefas vêm das definições de tarefa (Componentes Compartilhados); o SQL da aplicação cria-as com `meta.create_task(…)`.',
