  'rm.try_intro': 'Envia a requisição ao endpoint real: um PUT, POST ou DELETE altera dados. {as} uma conta emite um token de curta duração para ela, como faz App › REST API; sem conta, vê o que um chamador sem token recebe.',
  'rm.intro': 'Módulos dos serviços RESTful: um módulo é um caminho base de uma aplicação, os seus modelos são URIs com `:parameters` e cada modelo tem manipuladores por método com a sua origem: uma consulta de coleção, uma linha única, SQL, um bloco PL/pgSQL ou um recurso de mídia. Os manipuladores executam com a função de banco de dados da aplicação e o chamador como `meta.app_user()`, por isso aplicam-se as suas permissões e a segurança em nível de linha; os parâmetros são vinculados, nunca colados no SQL. Cada módulo tem um documento OpenAPI. Os módulos pertencem à sua aplicação: acompanham a sua exportação (também em Componentes Compartilhados › Serviços RESTful).',
  'rm.source_help': 'Binds, em maiúsculas: parâmetros de caminho ({params}), parâmetros de consulta e campos do corpo JSON; `:BODY` é o corpo inteiro; `:APP_USER` é o chamador. Os valores são vinculados, nunca colados no SQL. PL/pgSQL: um bloco (`declare … begin … end`, ou instruções) que responde com `perform meta.rest_reply(jsonb_build_object(…), 201)`. Mídia: uma consulta que devolve `content_type`, `content` e opcionalmente `filename`.',
  'rm.params_help': 'Um por linha: `name query|body [{types}] [required] [description]`. Vão para o documento OpenAPI e o formulário Experimentar; se faltar um obrigatório, a resposta é 400.',
  'rm.e.params_line': 'Parâmetros, linha {n}: escreva "name query" ou "name body" e, opcionalmente, um tipo ({types}), "required" e uma descrição.',
  'rm.e.choose_app': 'Escolha uma aplicação deste workspace.',
  'rm.e.base_path': 'O caminho base começa com uma letra minúscula: letras, dígitos, _ e - (no máximo 40).',
  'rm.e.title': 'O título tem de 1 a 200 caracteres.',
  'rm.created': 'Módulo {name} criado em {path}. Adicione agora um modelo.',
